"""Implementation Task Order V1, section 6 item 1: the four frozen hashes regenerated by data.py are identical
(protocol v1.1 sections 2.2, 2.5, 2.6, 2.7; PROTOCOL_FROZEN). Also: data.py's outputs are byte-identical to those of
the reference scripts in reports/round*/ that it was ported from (section 5, data.py row), and the Gate 0 part of the
leakage checks passes on them (protocol section 3)."""
import json
import os
import re
import subprocess
import sys

from metrix_e1 import data as D
from metrix_e1 import frozen as FZ
from metrix_e1 import leakage as LK

from conftest import PILOT

# The prefixes named in the Task Order (section 5, data.py row); the full values come from PROTOCOL_FROZEN.
TASK_ORDER_PREFIXES = {"facts": "406c8801", "train_S": "686fdd2f", "candidates": "e5d15c99", "anchor_texts": "8828bc4f"}


def test_four_frozen_hashes(fz, generated):
    got = fz.content_hashes(generated["dir"])                      # read back from the written files
    assert sorted(got) == sorted(TASK_ORDER_PREFIXES)
    for key, sha in got.items():
        assert sha == fz.data_hash(key), key
        assert sha.startswith(TASK_ORDER_PREFIXES[key]), key
    assert fz.check_data_dir(generated["dir"]) == got


def test_files_are_canonical(generated):
    """Written in the canonical form of protocol section 0, so byte_sha256 == canonical_sha256 for every file."""
    for name, h in D.file_hashes(generated["dir"]).items():
        assert h["byte_sha256"] == h["canonical_sha256"], name


# Row counts stated by the protocol text itself (independent of the parser under test, data.params):
# 2.1 "160 facts = 120 learned + 40 unread"; 2.3 one TRAIN statement per learned fact, 2 DEV questions per fact;
# 2.6 S = one statement per learned fact, Y "共 240 句"; 2.7 general DEV "共 100 个", anchor "前 512 篇".
PROTOCOL_ROWS = {"facts.jsonl": 160, "train_F.jsonl": 120, "train_S.jsonl": 120, "train_Y.jsonl": 240,
                 "dev_qa.jsonl": 320, "candidates.json": 160, "general_dev.jsonl": 100, "anchor_text.jsonl": 512}


def test_counts_and_ratio(fz, generated):
    """Row counts of 2.1 / 2.3 / 2.6 / 2.7 (protocol text, above) and the Y / F token counts that protocol 2.6 states
    for DATA_SEED (read from the frozen protocol text: "F 1,889 token,Y 2,260 token")."""
    for needle in ("**160 facts = 120 learned + 40 unread controls**", "共 240 句", "共 100 个", "前 512 篇"):
        assert needle in fz.protocol_text, needle
    assert fz.data_manifest["facts"]["total"] == PROTOCOL_ROWS["facts.jsonl"]
    assert generated["info"]["rows"] == PROTOCOL_ROWS
    m = re.findall(r"F ([\d,]+) token,Y ([\d,]+) token", fz.protocol_text)
    assert len(m) == 1
    r = generated["info"]["y_ratio"]
    assert (r["F_tokens"], r["Y_tokens"]) == tuple(int(x.replace(",", "")) for x in m[0])
    assert generated["info"]["general_dev"]["windows"] == generated["info"]["rows"]["general_dev.jsonl"]
    # every row decoded and parsed is a DEV row: as many as the row-prefix count of the DEV split
    assert generated["info"]["general_dev"]["parsed_rows"] == generated["info"]["general_dev"]["rows_by_split"]["dev"]


def test_no_test_file(generated):
    assert not any((generated["dir"] / n).exists() for n in D.TEST_FILES)


def _run(args, **kw):
    env = dict(os.environ, HF_HUB_OFFLINE="1", PYTHONHASHSEED="0")
    r = subprocess.run([sys.executable, "-I", *map(str, args)], capture_output=True, text=True, env=env, cwd=PILOT, **kw)
    assert r.returncode == 0, r.stdout + r.stderr
    return r.stdout


_ROW_SPLIT = re.compile(rb'\{"domain": "[^"\\]*", "split": "([^"\\]*)", ')


def _dev_rows_only(tmp_path):
    """The reference script reports/round5/l6_check.py reads eval_sets.jsonl in text mode, which decodes every row
    (test rows too) from UTF-8 before skipping the non-dev ones (code-reviewer, stage B fix commit, MAJOR; data-auditor
    round-2 observation 1; pending Review Gate). It is given instead a copy holding only the DEV rows: the rows are
    selected on the raw bytes of their split field (counting / parsing the split field is not reading TEST, protocol
    section 3), copied byte for byte, and no test row is decoded. The script pins the file's sha256 through the
    manifest, so a copy of DATA_MANIFEST.json with that one value replaced goes with it. The script itself is not
    changed; its selection (first 25 DEV rows per domain, file order) is unaffected by the removed test rows."""
    src = PILOT.parents[1] / "research/mini_mythos/stage1/results/r1/eval_sets.jsonl"
    out = tmp_path / "eval_sets_dev_rows.jsonl"
    n = {"dev": 0, "other": 0}
    with open(src, "rb") as fi, open(out, "wb") as fo:
        for line in fi:
            m = _ROW_SPLIT.match(line)
            assert m is not None
            if m.group(1) == b"dev":
                fo.write(line)
                n["dev"] += 1
            else:
                n["other"] += 1
    assert n == {"dev": 400, "other": 800}
    manifest = json.loads((PILOT / "DATA_MANIFEST.json").read_text(encoding="utf-8"))
    manifest["general_text"]["source_file_sha256"] = FZ.file_sha256(out)
    mpath = tmp_path / "DATA_MANIFEST_dev_rows.json"
    mpath.write_text(json.dumps(manifest, ensure_ascii=False), encoding="utf-8")
    return out, mpath


def test_byte_identical_to_reference_scripts(inputs_dir, generated, tmp_path):
    """reports/round2/anchor_check.py, gen_facts.py, reports/round7/gen_s_cands.py and reports/round5/l6_check.py,
    run on the same inputs (l6_check.py on the DEV rows of eval_sets.jsonl only, see _dev_rows_only), give
    byte-identical facts, anchor texts, train_S.jsonl, candidates.json and general DEV windows."""
    rep = PILOT / "reports"
    tok = inputs_dir / "qwen_tokenizer"
    _run([rep / "round2/anchor_check.py", "--manifest", "DATA_MANIFEST.json", "--tokenizer-dir", tok,
          "--cache-dir", inputs_dir / "anchor_source", "--anchor-out", tmp_path / "anchor.json"])
    _run([rep / "round2/gen_facts.py", "--manifest", "DATA_MANIFEST.json", "--tokenizer-dir", tok,
          "--anchor", tmp_path / "anchor.json", "--out", tmp_path / "facts.json"])
    _run([rep / "round7/gen_s_cands.py", "--facts", tmp_path / "facts.json", "--data-manifest", "DATA_MANIFEST.json",
          "--split-manifest", "SPLIT_MANIFEST.json", "--out-dir", tmp_path / "sc"])
    dev_rows, manifest = _dev_rows_only(tmp_path)
    _run([rep / "round5/l6_check.py", "--eval-sets", dev_rows,
          "--parcae-tokenizer", inputs_dir / "parcae_tokenizer/tokenizer.json", "--manifest", manifest,
          "--tokenizer-dir", tok, "--anchor", tmp_path / "anchor.json", "--general-out", tmp_path / "general.json"])
    files = generated["files"]
    facts = FZ.read_jsonl(generated["dir"] / "facts.jsonl")
    assert (tmp_path / "facts.json").read_bytes() == FZ.canonical_bytes(facts)
    assert (tmp_path / "sc/train_S.jsonl").read_bytes() == files["train_S.jsonl"]
    assert (tmp_path / "sc/candidates.json").read_bytes() == files["candidates.json"]
    ref_anchor = json.loads((tmp_path / "anchor.json").read_text(encoding="utf-8"))["texts"]
    ours = FZ.read_jsonl(generated["dir"] / "anchor_text.jsonl")
    assert FZ.canonical_bytes(ref_anchor) == FZ.canonical_bytes([r["text"] for r in ours])
    ref_general = json.loads((tmp_path / "general.json").read_text(encoding="utf-8"))
    ours = FZ.read_jsonl(generated["dir"] / "general_dev.jsonl")
    assert FZ.canonical_bytes([{k: g[k] for k in ("domain", "doc_id", "ids", "text")} for g in ref_general]) == \
        FZ.canonical_bytes(ours)


def test_leakage_gate0_passes(fz, generated):
    report = LK.run_gate0(fz.split_manifest, LK.load_data(generated["dir"]))
    assert report["result"] == "PASS", report
    assert set(report["checks"]) == set(LK.CHECKS)


def test_y_f_ratio_with_and_without_endoftext(generated):
    """Review Gate ruling on stage A, item 3: the ratio counts one <|endoftext|> per sequence (the protocol check);
    the ratio without it is reported too; both lie in the protocol interval [0.80, 1.25] (SEARCH_SPACE.json)."""
    yr = generated["info"]["y_ratio"]
    assert (yr["F_tokens"], yr["Y_tokens"]) == (1889, 2260)                       # protocol 2.6
    assert yr["F_tokens_without_endoftext"] == yr["F_tokens"] - 120 == 1769      # 120 F sequences
    assert yr["Y_tokens_without_endoftext"] == yr["Y_tokens"] - 240 == 2020      # 240 Y sequences
    lo, hi = yr["bounds"]
    assert (lo, hi) == (0.80, 1.25)
    assert lo <= yr["ratio"] <= hi and lo <= yr["ratio_without_endoftext"] <= hi
    assert round(yr["ratio"], 4) == 1.1964 and round(yr["ratio_without_endoftext"], 4) == 1.1419
